Dataspatium.assets.register("presets/api/geodataportalen.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"geodataportalen\",\n  \"name\": \"Geodataportalen (sök geodata)\",\n  \"publisher\": \"Lantmäteriet (Geodatarådet)\",\n  \"description\": \"Sök bland myndigheters, regioners och kommuners geodata i den nationella katalogen. Resultatet är en tabell med titel, organisation och tjänsteadresser (WFS, OGC API Features, ArcGIS, WMS); en tjänst kan läggas till som geodatakälla med ett klick.\",\n  \"docs\": \"https://www.geodata.se/geodataportalen/\",\n  \"license\": {\n    \"name\": \"Metadata: öppna data\",\n    \"url\": \"https://www.geodata.se/geodataportalen/\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://www.geodata.se/geodataportalen/srv/api/search/records\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geoportal\"\n  },\n  \"endpoints\": [\n    {\n      \"id\": \"search\",\n      \"name\": \"Sök geodata\",\n      \"description\": \"Fritextsökning i katalogen (Elasticsearch). Resultatet listar tjänsterna per post.\",\n      \"method\": \"POST\",\n      \"path\": \"/_search\",\n      \"bodyType\": \"json\",\n      \"body\": {\n        \"query\": {\n          \"query_string\": {\n            \"query\": \"{q}\",\n            \"default_operator\": \"AND\"\n          }\n        },\n        \"size\": 50,\n        \"_source\": [\n          \"resourceTitleObject\",\n          \"resourceAbstractObject\",\n          \"resourceType\",\n          \"OrgForResourceObject\",\n          \"OrgForResource\",\n          \"contact\",\n          \"link\"\n        ]\n      },\n      \"params\": [\n        {\n          \"name\": \"q\",\n          \"in\": \"template\",\n          \"label\": \"Sökord\",\n          \"type\": \"string\",\n          \"required\": true,\n          \"example\": \"detaljplan\"\n        }\n      ],\n      \"response\": {\n        \"format\": \"geonetwork\"\n      },\n      \"dataset\": {\n        \"name\": \"Geodataportalen: {q}\"\n      }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Geodataportalen (search geodata)\",\n      \"description\": \"Search the geodata of Swedish agencies, regions and municipalities in the national catalogue. The result is a table with title, organisation and service addresses (WFS, OGC API Features, ArcGIS, WMS); a service can be added as a geodata source with one click.\",\n      \"endpoints\": {\n        \"search\": {\n          \"name\": \"Search geodata\",\n          \"description\": \"Free-text search in the catalogue (Elasticsearch). The result lists the services per record.\",\n          \"params\": {\n            \"q\": {\n              \"label\": \"Search words\"\n            }\n          }\n        }\n      }\n    },\n    \"da\": {\n      \"name\": \"Geodataportalen (søg geodata)\",\n      \"description\": \"Søg blandt svenske myndigheders, regioners og kommuners geodata i det nationale katalog. Resultatet er en tabel med titel, organisation og tjenesteadresser (WFS, OGC API Features, ArcGIS, WMS); en tjeneste kan tilføjes som geodatakilde med ét klik.\",\n      \"endpoints\": {\n        \"search\": {\n          \"name\": \"Søg geodata\",\n          \"description\": \"Fritekstsøgning i kataloget (Elasticsearch). Resultatet lister tjenesterne pr. post.\",\n          \"params\": {\n            \"q\": {\n              \"label\": \"Søgeord\"\n            }\n          }\n        }\n      }\n    },\n    \"nb\": {\n      \"name\": \"Geodataportalen (søk geodata)\",\n      \"description\": \"Søk blant svenske etaters, regioners og kommuners geodata i den nasjonale katalogen. Resultatet er en tabell med tittel, organisasjon og tjenesteadresser (WFS, OGC API Features, ArcGIS, WMS); en tjeneste kan legges til som geodatakilde med ett klikk.\",\n      \"endpoints\": {\n        \"search\": {\n          \"name\": \"Søk geodata\",\n          \"description\": \"Fritekstsøk i katalogen (Elasticsearch). Resultatet lister tjenestene per post.\",\n          \"params\": {\n            \"q\": {\n              \"label\": \"Søkeord\"\n            }\n          }\n        }\n      }\n    },\n    \"fi\": {\n      \"name\": \"Geodataportalen (hae paikkatietoa)\",\n      \"description\": \"Hae Ruotsin viranomaisten, alueiden ja kuntien paikkatietoja kansallisesta luettelosta. Tulos on taulukko, jossa on otsikko, organisaatio ja palveluosoitteet (WFS, OGC API Features, ArcGIS, WMS); palvelun voi lisätä paikkatietolähteeksi yhdellä napsautuksella.\",\n      \"endpoints\": {\n        \"search\": {\n          \"name\": \"Hae paikkatietoa\",\n          \"description\": \"Vapaatekstihaku luettelosta (Elasticsearch). Tulos luettelee palvelut tietuetta kohden.\",\n          \"params\": {\n            \"q\": {\n              \"label\": \"Hakusanat\"\n            }\n          }\n        }\n      }\n    },\n    \"is\": {\n      \"name\": \"Geodataportalen (leita í landupplýsingum)\",\n      \"description\": \"Leitaðu í landupplýsingum sænskra stofnana, landshluta og sveitarfélaga í landsskránni. Niðurstaðan er tafla með titli, stofnun og þjónustuvistföngum (WFS, OGC API Features, ArcGIS, WMS); þjónustu má bæta við sem landupplýsingauppsprettu með einum smelli.\",\n      \"endpoints\": {\n        \"search\": {\n          \"name\": \"Leita í landupplýsingum\",\n          \"description\": \"Frjáls textaleit í skránni (Elasticsearch). Niðurstaðan telur upp þjónustur hverrar færslu.\",\n          \"params\": {\n            \"q\": {\n              \"label\": \"Leitarorð\"\n            }\n          }\n        }\n      }\n    }\n  }\n}\n");
